insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('rss', 'https://skift.com/feed/', 'Skift', 'https://skift.com/', true, '{travel,strategy}', 'The main daily business news for travel. Strong on OTAs, Airbnb, AI agents and travel demand, so it is still the best base source.', '[{"label":"In Travel Trends Podcast''s ''Top 10 Travel Industry Newsletters'' (Skift Daily)","url":"https://www.traveltrendspodcast.com/blog/top-10-travel-industry-newsletters"},{"label":"First pick in Revfine''s list of travel industry podcasts for professionals","url":"https://www.revfine.com/travel-industry-podcasts/"}]'::jsonb, 0.9) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('rss', 'https://traveltechessentialist.substack.com/feed', 'Travel Tech Essentialist', 'https://traveltechessentialist.substack.com/', true, '{travel,strategy}', 'A deep newsletter every two weeks on distribution, OTA stocks and AI in travel, by the co-founder of eDreams. It gives a strategy view, not only news.', '[{"label":"Author Mauricio Prieto is the founder of eDreams (Mogu list of best travel newsletters)","url":"https://moguplatform.com/en/blog/10-best-travel-industry-newsletters"},{"label":"#1 in Travel Trends Podcast''s ''Top 10 Travel Industry Newsletters''","url":"https://www.traveltrendspodcast.com/blog/top-10-travel-industry-newsletters"},{"label":"Calls itself the ''#1 ranked travel business newsletter on Substack'' (self-stated)","url":"https://traveltechessentialist.substack.com/"}]'::jsonb, 0.9) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('rss', 'https://tnmt.com/feed/', 'TNMT — Travel & Mobility Tech (Lufthansa Innovation Hub)', 'https://tnmt.com/', true, '{travel,ai}', 'Data-based research on travel and mobility tech, startups and investment. Good for ground transport and for how AI agents may change booking.', '[{"label":"In Travel Trends Podcast''s ''Top 10 Travel Industry Newsletters'' (Lufthansa Innovation Hub – TNMT)","url":"https://www.traveltrendspodcast.com/blog/top-10-travel-industry-newsletters"},{"label":"Research team from Lufthansa Innovation Hub, with mobility experience (FreeNow, DLR)","url":"https://tnmt.com/about/"}]'::jsonb, 0.85) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('podcast', 'https://www.omnycontent.com/d/playlist/37ffe223-859b-4955-b6ca-aab8005d8b43/879749c5-2eb8-4629-a791-ae8700ce6ce8/95b45464-58cb-4896-b3c5-b1000134803a/podcast.rss', 'In Phocus (PhocusWire)', 'https://www.phocuswire.com/', true, '{travel,startups}', 'Weekly talks with travel tech leaders, about AI, M&A and distribution. It replaces the PhocusWire website feed, which blocks bots.', '[{"label":"PhocusWire is in Travel Trends Podcast''s ''Top 10 Travel Industry Newsletters''","url":"https://www.traveltrendspodcast.com/blog/top-10-travel-industry-newsletters"},{"label":"5.0★ on Apple Podcasts, but only 3 ratings (weak signal)","url":"https://podcasts.apple.com/us/podcast/in-phocus/id1727229211"}]'::jsonb, 0.8) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('rss', 'https://www.ttgasia.com/feed/', 'TTG Asia', 'https://www.ttgasia.com/', true, '{travel,markets}', 'Daily trade news from Asia-Pacific, where 12Go works: Trip.com, airlines, tourism boards and demand in each country.', '[{"label":"Asia-Pacific travel trade title since 1974 (self-described)","url":"https://www.ttgasia.com/about-us/"}]'::jsonb, 0.75) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('podcast', 'https://feeds.megaphone.fm/SKIFT8999081027', 'The Skift Travel Podcast', 'https://skift.com/', true, '{travel,strategy}', 'Every week Skift''s research head Seth Borko explains one big trend with data. Good for long-term thinking about demand.', '[{"label":"4.2★ from 39 ratings on Apple Podcasts","url":"https://podcasts.apple.com/us/podcast/the-skift-travel-podcast/id999975096"},{"label":"First pick in Revfine''s list of travel industry podcasts","url":"https://www.revfine.com/travel-industry-podcasts/"}]'::jsonb, 0.85) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) select 'book', 'The Upstarts — Brad Stone', 'https://www.goodreads.com/book/show/29905580-the-upstarts', true, '{travel,startups}', 'The story of Uber and Airbnb: how marketplaces for rides and stays grew, fought regulators and won. Very close to a mobility and travel marketplace.', '[{"label":"Literary Review calls it an ''excellent'' account of Uber and Airbnb","url":"https://literaryreview.co.uk/fair-share"}]'::jsonb, 0.85 where not exists (select 1 from sources where kind = 'book' and owner_user_id is null and title = 'The Upstarts — Brad Stone');
