insert into sources (kind, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) select 'book', 'Outlive — Peter Attia', 'https://peterattiamd.com/outlive/', true, '{health}', 'A practical guide to living longer and healthier: exercise, sleep, food and early checks. Replaces ''Why We Sleep'', which has known accuracy problems.', '[{"label":"#1 New York Times bestseller","url":"https://peterattiamd.com/outlive/"},{"label":"Critique of ''Why We Sleep'' (reason for replacing it)","url":"https://guzey.com/books/why-we-sleep/"}]'::jsonb, 0.75 where not exists (select 1 from sources where kind = 'book' and owner_user_id is null and title = 'Outlive — Peter Attia');
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('rss', 'https://www.carbonbrief.org/feed/', 'Carbon Brief', 'https://www.carbonbrief.org', true, '{climate,science}', 'Clear, data-driven reporting on climate science, policy and energy. Very trusted by experts.', '[{"label":"Press Gazette Future of Media Awards 2024: website of the year (specialist)","url":"https://www.carbonbrief.org/about-us/"},{"label":"Funding is shown openly (European Climate Foundation, Meliore Foundation)","url":"https://www.carbonbrief.org/about-us/"}]'::jsonb, 0.9) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('rss', 'https://heatmap.news/feeds/feed.rss', 'Heatmap News', 'https://heatmap.news', true, '{climate,markets}', 'Fast daily news on climate, clean energy, politics and business. Good for knowing what changed today.', '[{"label":"Won the 2025 National Magazine Award for Service Journalism","url":"https://heatmap.news/sparks/heatmap-national-magazine-award"}]'::jsonb, 0.85) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, feed_url, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) values ('podcast', 'https://feeds.megaphone.fm/catalyst', 'Catalyst with Shayle Kann', 'https://www.latitudemedia.com/podcasts/catalyst/', true, '{climate,startups}', 'A climate-tech investor talks each week with experts about energy, new technology and money. Useful for business readers.', '[{"label":"New episode every Thursday; host is a veteran energy investor","url":"https://www.latitudemedia.com/podcasts/catalyst/"}]'::jsonb, 0.85) on conflict (feed_url) where feed_url is not null and owner_user_id is null do update set kind = excluded.kind, title = excluded.title, url = excluded.url, is_discovery = true, discovery_categories = excluded.discovery_categories, why = excluded.why, evidence = excluded.evidence, discovery_trust = excluded.discovery_trust;
insert into sources (kind, title, url, is_discovery, discovery_categories, why, evidence, discovery_trust) select 'book', 'Not the End of the World — Hannah Ritchie', 'https://www.hachettebookgroup.com/titles/hannah-ritchie/not-the-end-of-the-world/9780316536752/', true, '{climate}', 'A data scientist shows with clear data where we are winning and losing on climate and nature. Hopeful but honest.', '[{"label":"Bill Gates reviewed it as an optimistic, data-rich book","url":"https://www.gatesnotes.com/Not-the-End-of-the-World"}]'::jsonb, 0.85 where not exists (select 1 from sources where kind = 'book' and owner_user_id is null and title = 'Not the End of the World — Hannah Ritchie');
